const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brazil = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Brazil'))
    .geometry();

  // 2. Data Acquisition & Check
  const landcover = ee.ImageCollection('MODIS/006/MCD12Q1')
    .select('LC_Type1');

  // Get 2003 image
  const lc2003 = landcover.filter(ee.Filter.calendarRange(2003, 2003, 'year')).first();
  const lc2019 = landcover.filter(ee.Filter.calendarRange(2019, 2019, 'year')).first();

  // Check if images exist
  const col2003Size = landcover.filter(ee.Filter.calendarRange(2003, 2003, 'year')).size().getInfo();
  const col2019Size = landcover.filter(ee.Filter.calendarRange(2019, 2019, 'year')).size().getInfo();

  if (col2003Size === 0 || col2019Size === 0) {
    console.log(`2003 Images: ${col2003Size}, 2019 Images: ${col2019Size}`);
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`2003 Images: ${col2003Size}, 2019 Images: ${col2019Size}`);

  // 3. Processing - Create cropland masks (class 12 = Croplands, 14 = Cropland/Natural Vegetation Mosaic)
  const cropland2003 = lc2003.eq(12).or(lc2003.eq(14));
  const cropland2019 = lc2019.eq(12).or(lc2019.eq(14));

  // 4. Calculation - Calculate cropland area in km²
  const pixelArea = ee.Image.pixelArea().divide(1e6); // Convert to km²

  const area2003Result = cropland2003.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: brazil,
    scale: 5000,
    maxPixels: 1e9
  });

  const area2019Result = cropland2019.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: brazil,
    scale: 5000,
    maxPixels: 1e9
  });

  // Get pixel counts for validation
  const count2003Result = cropland2003.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: brazil,
    scale: 5000,
    maxPixels: 1e9
  });

  const count2019Result = cropland2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: brazil,
    scale: 5000,
    maxPixels: 1e9
  });

  const area2003 = area2003Result.get('LC_Type1').getInfo();
  const area2019 = area2019Result.get('LC_Type1').getInfo();
  const count2003 = count2003Result.get('LC_Type1').getInfo();
  const count2019 = count2019Result.get('LC_Type1').getInfo();

  // 5. Validation & Final Answer
  console.log(`2003 Cropland Area: ${area2003.toFixed(2)} km² (Pixels: ${count2003})`);
  console.log(`2019 Cropland Area: ${area2019.toFixed(2)} km² (Pixels: ${count2019})`);

  if (count2003 === 0 || count2019 === 0) {
    console.log("No valid cropland pixels found.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (area2003 === null || area2019 === null || isNaN(area2003) || isNaN(area2019)) {
    console.log("Calculation failed (null or NaN result).");
    console.log("<answer>C3</answer>");
    return;
  }

  const change = area2019 - area2003;
  const percentChange = ((change / area2003) * 100).toFixed(2);
  console.log(`Change: ${change.toFixed(2)} km² (${percentChange}%)`);

  if (area2019 > area2003) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
